def create_multipliers(n: int) -> list:
    """Buggy: 루프 변수의 늦은 바인딩으로 모든 함수가 마지막 i 값을 참조함"""
    if n < 0:
        raise ValueError('n must be non-negative')
    multipliers = []
    for i in range(n):
        multipliers.append(lambda x: x * i)  # Bug: i가 클로저로 캡처되어 마지막 값만 참조
    return multipliers

def create_multipliers(n: int) -> list:
    """Buggy: 리스트 컴프리헨션에서도 늦은 바인딩 발생"""
    if n < 0:
        raise ValueError('n must be non-negative')
    return [lambda x: x * i for i in range(n)]  # Bug: 컴프리헨션도 늦은 바인딩 적용

def create_multipliers(n: int) -> list:
    """Buggy: n=0일 때 잘못된 예외 발생"""
    if n <= 0:
        raise ValueError('n must be positive')  # Bug: 0도 유효한 입력이어야 함
    multipliers = []
    for i in range(n):
        multipliers.append(lambda x, i=i: x * i)
    return multipliers
